begin;
create table public.community_posts (id uuid primary key default gen_random_uuid(), owner_user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, anonymous_alias text not null, topic text not null check (topic in ('job-search','career','application','work-life')), title text not null check (char_length(title) between 2 and 110), body text not null check (char_length(body) between 5 and 5000), status text not null default 'PUBLISHED' check (status in ('PUBLISHED','HIDDEN','REMOVED')), recommendation_count integer not null default 0 check (recommendation_count >= 0), comment_count integer not null default 0 check (comment_count >= 0), created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()));
create index community_posts_latest_idx on public.community_posts (created_at desc) where status = 'PUBLISHED';
create index community_posts_popular_idx on public.community_posts (recommendation_count desc, comment_count desc, created_at desc) where status = 'PUBLISHED';
create trigger community_posts_updated_at before update on public.community_posts for each row execute function public.set_updated_at();
create table public.community_comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.community_posts(id) on delete cascade, owner_user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, anonymous_alias text not null, body text not null check (char_length(body) between 2 and 1000), status text not null default 'PUBLISHED' check (status in ('PUBLISHED','HIDDEN','REMOVED')), created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()));
create index community_comments_post_idx on public.community_comments (post_id, created_at asc) where status = 'PUBLISHED';
create trigger community_comments_updated_at before update on public.community_comments for each row execute function public.set_updated_at();
create table public.community_recommendations (post_id uuid not null references public.community_posts(id) on delete cascade, owner_user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, created_at timestamptz not null default timezone('utc', now()), primary key (post_id, owner_user_id));
create table public.community_attachments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.community_posts(id) on delete cascade, owner_user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, storage_path text not null unique, filename text not null check (char_length(filename) between 1 and 160), mime_type text not null check (mime_type in ('image/jpeg','image/png','image/webp','application/pdf')), byte_size integer not null check (byte_size > 0 and byte_size <= 8388608), created_at timestamptz not null default timezone('utc', now()));
create index community_attachments_post_idx on public.community_attachments (post_id, created_at asc);
create table public.community_reports (id uuid primary key default gen_random_uuid(), reporter_user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, subject_type text not null check (subject_type in ('POST','COMMENT')), subject_id uuid not null, reason text not null check (reason in ('PERSONAL_INFORMATION','HARASSMENT','MISINFORMATION','SPAM','OTHER')), note text check (note is null or char_length(note) <= 500), status text not null default 'OPEN' check (status in ('OPEN','REVIEWED','CLOSED')), created_at timestamptz not null default timezone('utc', now()), unique (reporter_user_id, subject_type, subject_id));
create function public.set_community_alias() returns trigger language plpgsql security invoker set search_path = '' as $$ begin new.anonymous_alias := '익명 ' || upper(substr(md5(new.owner_user_id::text), 1, 4)); return new; end; $$;
create trigger community_post_alias before insert on public.community_posts for each row execute function public.set_community_alias();
create trigger community_comment_alias before insert on public.community_comments for each row execute function public.set_community_alias();
create function public.sync_community_post_counts() returns trigger language plpgsql security definer set search_path = '' as $$ declare target_post_id uuid; begin target_post_id := coalesce(new.post_id, old.post_id); update public.community_posts p set recommendation_count = (select count(*) from public.community_recommendations r where r.post_id = target_post_id), comment_count = (select count(*) from public.community_comments c where c.post_id = target_post_id and c.status = 'PUBLISHED') where p.id = target_post_id; return coalesce(new, old); end; $$;
create trigger community_recommendation_count after insert or delete on public.community_recommendations for each row execute function public.sync_community_post_counts();
create trigger community_comment_count after insert or update or delete on public.community_comments for each row execute function public.sync_community_post_counts();
alter table public.community_posts enable row level security; alter table public.community_comments enable row level security; alter table public.community_recommendations enable row level security; alter table public.community_attachments enable row level security; alter table public.community_reports enable row level security;
create policy "published community posts are public" on public.community_posts for select using (status = 'PUBLISHED' or owner_user_id = (select auth.uid()));
create policy "members create own community posts" on public.community_posts for insert to authenticated with check (owner_user_id = (select auth.uid()));
create policy "members update own community posts" on public.community_posts for update to authenticated using (owner_user_id = (select auth.uid())) with check (owner_user_id = (select auth.uid()));
create policy "members delete own community posts" on public.community_posts for delete to authenticated using (owner_user_id = (select auth.uid()));
create policy "published community comments are public" on public.community_comments for select using (status = 'PUBLISHED' or owner_user_id = (select auth.uid()));
create policy "members create own community comments" on public.community_comments for insert to authenticated with check (owner_user_id = (select auth.uid()) and exists (select 1 from public.community_posts p where p.id = post_id and p.status = 'PUBLISHED'));
create policy "members remove own community comments" on public.community_comments for delete to authenticated using (owner_user_id = (select auth.uid()));
create policy "members read own recommendations" on public.community_recommendations for select to authenticated using (owner_user_id = (select auth.uid()));
create policy "members recommend as themselves" on public.community_recommendations for insert to authenticated with check (owner_user_id = (select auth.uid()) and exists (select 1 from public.community_posts p where p.id = post_id and p.status = 'PUBLISHED'));
create policy "members remove own recommendation" on public.community_recommendations for delete to authenticated using (owner_user_id = (select auth.uid()));
create policy "community attachment metadata for members" on public.community_attachments for select to authenticated using (exists (select 1 from public.community_posts p where p.id = post_id and p.status = 'PUBLISHED') or owner_user_id = (select auth.uid()));
create policy "members add attachment metadata to own post" on public.community_attachments for insert to authenticated with check (owner_user_id = (select auth.uid()) and exists (select 1 from public.community_posts p where p.id = post_id and p.owner_user_id = (select auth.uid())));
create policy "members delete own attachment metadata" on public.community_attachments for delete to authenticated using (owner_user_id = (select auth.uid()));
create policy "members create own reports" on public.community_reports for insert to authenticated with check (reporter_user_id = (select auth.uid()));
create policy "members read own reports" on public.community_reports for select to authenticated using (reporter_user_id = (select auth.uid()));
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('community-attachments','community-attachments',false,8388608,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
create policy "members upload own community attachments" on storage.objects for insert to authenticated with check (bucket_id = 'community-attachments' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "signed in members read published community attachments" on storage.objects for select to authenticated using (bucket_id = 'community-attachments' and exists (select 1 from public.community_attachments a join public.community_posts p on p.id = a.post_id where a.storage_path = name and p.status = 'PUBLISHED'));
create policy "members read pending own community attachments" on storage.objects for select to authenticated using (bucket_id = 'community-attachments' and owner_id = (select auth.uid())::text);
create policy "members delete own community attachments" on storage.objects for delete to authenticated using (bucket_id = 'community-attachments' and owner_id = (select auth.uid())::text);
commit;